CREATE TABLE openings (
  id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, company_id INTEGER NOT NULL, point_id INTEGER NOT NULL, doc_date TEXT NOT NULL,
  stock_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ciorna', notes TEXT, created TEXT, created_by TEXT, finalized_at TEXT, finalized_by TEXT
);
CREATE TABLE opening_items (
  id INTEGER PRIMARY KEY, opening_id INTEGER NOT NULL REFERENCES openings(id), article_id INTEGER NOT NULL, ewc_id INTEGER, hu_id INTEGER,
  lot TEXT NOT NULL, kg REAL NOT NULL, pcs INTEGER, org_id INTEGER, regime TEXT DEFAULT 'propriu', price REAL, created TEXT, created_by TEXT
);
CREATE TABLE offers (
  id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ciorna', company_id INTEGER NOT NULL,
  point_id INTEGER NOT NULL, partners TEXT DEFAULT '[]', points TEXT DEFAULT '[]', valid_from TEXT NOT NULL, valid_to TEXT NOT NULL,
  currency TEXT DEFAULT 'RON', notes TEXT, created TEXT, created_by TEXT, issued_at TEXT, issued_by TEXT, closed_at TEXT, closed_by TEXT, close_reason TEXT
);
CREATE TABLE offer_lines (
  id INTEGER PRIMARY KEY, offer_id INTEGER NOT NULL REFERENCES offers(id), article_id INTEGER NOT NULL, ewc_id INTEGER, qty REAL, um TEXT,
  price REAL NOT NULL, notes TEXT, photo_id TEXT, photo_name TEXT
);
